/** The 1-based column of the first non-space character of `raw`. */
export function indent(raw) {
  return raw.length - raw.trimStart().length + 1
}

/**
 * The 1-based column a value occupies on its raw line.
 * @param {string} raw - the untrimmed line the value was written on.
 * @param {string} trimmed - `raw.trim()`, already split into `name/key` and value around `split`.
 * @param {number} split - the 0-based index of the separating `=` within `trimmed`.
 * @returns {number} the column of the value's first character, or, when the value is empty
 *   once trimmed, one past the line's last non-space character.
 */
export function valuePosition(raw, trimmed, split) {
  const after = trimmed.slice(split + 1)
  const leading = after.length - after.trimStart().length
  if (after.trim() === '') return indent(raw) + trimmed.length
  return indent(raw) + split + 1 + leading
}
"}

