import { indent, valuePosition } from './position.js'
import { keyForEnvName } from './schema.js'

/** One refusal of an environment line, carrying the 1-based line and column it was read at. */
export class EnvError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {number} column - the 1-based column of the raw line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, column, message) {
    super(message)
    this.name = 'EnvError'
    this.line = line
    this.column = column
  }
}

/**
 * Parse environment text into its settings.
 * @param {string} text - the whole standard input.
 * @returns {Map<string, {text: string, line: number, column: number}>} each schema key's raw
 *   value and the position it was written at.
 * @throws {EnvError} on the first line the grammar refuses.
 */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const column = indent(raw)
    const split = trimmed.indexOf('=')
    if (split === -1) throw new EnvError(line, column, 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new EnvError(line, column, 'expected a variable name')
    const key = keyForEnvName(name)
    if (key === undefined) throw new EnvError(line, column, `unknown environment variable ${name}`)
    if (values.has(key)) throw new EnvError(line, column, `${name} is set twice`)
    values.set(key, { text: trimmed.slice(split + 1).trim(), line, column: valuePosition(raw, trimmed, split) })
  }
  return values
}
"}

