/** The environment variable name a setting key travels under. */
function envName(key) {
  return `CONF_${key.toUpperCase().replace(/\./gu, '_')}`
}

const BY_ENV_NAME = new Map(SETTINGS.map(declared => [envName(declared.key), declared.key]))

/**
 * The setting key one environment variable name names, or undefined when none matches.
 * @param {string} name - the variable name as written, e.g. `CONF_SERVER_PORT`.
 * @returns {string | undefined} the dotted setting key.
 */
export function keyForEnvName(name) {
  return BY_ENV_NAME.get(name)
}

const DURATION = /^([0-9]+)(ms|s|m|h)$/u
const DURATION_MS = { ms: 1n, s: 1000n, m: 60000n, h: 3600000n }

/**
 * Coerce a setting's raw text to its declared type.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting.
 * @param {string} text - the raw text a layer wrote, or the schema default.
 * @returns {{ok: true, value: string} | {ok: false, message: string}} the coerced text to
 *   render, or the failure message the specification words (without its position).
 */
export function coerce(declared, text) {
  switch (declared.type) {
    case 'string':
      return { ok: true, value: text }
    case 'integer':
      if (/^-?(0|[1-9][0-9]*)$/u.test(text)) return { ok: true, value: text }
      return { ok: false, message: `${declared.key} is not an integer: ${text}` }
    case 'boolean':
      if (text === 'true' || text === 'false') return { ok: true, value: text }
      return { ok: false, message: `${declared.key} is not a boolean: ${text}` }
    case 'enum':
      if (declared.members.includes(text)) return { ok: true, value: text }
      return { ok: false, message: `${declared.key} is not one of ${declared.members.join('|')}: ${text}` }
    case 'duration': {
      const match = DURATION.exec(text)
      if (!match) return { ok: false, message: `${declared.key} is not a duration: ${text}` }
      const ms = BigInt(match[1]) * DURATION_MS[match[2]]
      return { ok: true, value: ms.toString() }
    }
    case 'list': {
      if (text === '') return { ok: true, value: '' }
      const items = text.split(',').map(item => item.trim())
      if (items.some(item => item === '')) return { ok: false, message: `${declared.key} has an empty item: ${text}` }
      const seen = new Set()
      const kept = []
      for (const item of items) {
        if (seen.has(item)) continue
        seen.add(item)
        kept.push(item)
      }
      return { ok: true, value: kept.join(',') }
    }
    default:
      throw new Error(`unknown type ${declared.type}`)
  }
