/** The command: `dump <file>`, `get <file> <key>`, `load <base> <site>` and `origin <base> <site>`. */

import { existsSync, readFileSync } from 'node:fs'
import { EnvError, parse as parseEnv } from './env.js'
import { IniError, parse as parseIni } from './ini.js'
import { merge } from './layer.js'
import { coerce, SETTINGS, setting } from './schema.js'

const USAGE = 'usage: cli.js dump <file>|get <file> <key>|load <base> <site>|origin <base> <site>'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** One INI file's settings, refused at its own position when the grammar rejects it. */
function readIni(path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  try {
    return parseIni(readFileSync(path, 'utf8'))
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
}

/** Refuse the first key, in the order the file wrote them, that the schema does not know. */
function checkKnown(path, values) {
  for (const [key, entry] of values) {
    if (setting(key) === undefined) fail(`${path}:${entry.line}:${entry.column}: unknown setting ${key}`)
  }
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
if (argv.length !== arity[mode]) fail(USAGE)

const out = []

if (mode === 'dump' || mode === 'get') {
  const values = readIni(argv[1])
  const raw = key => (values.has(key) ? values.get(key).text : setting(key).default)
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
} else {
  const [basePath, sitePath] = [argv[1], argv[2]]
  const baseValues = readIni(basePath)
  checkKnown(basePath, baseValues)
  const siteValues = readIni(sitePath)
  checkKnown(sitePath, siteValues)

  let envValues
  try {
    envValues = parseEnv(readFileSync(0, 'utf8'))
  } catch (error) {
    if (!(error instanceof EnvError)) throw error
    envValues = fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }

  const merged = merge([
    { name: 'base', path: basePath, values: baseValues },
    { name: 'site', path: sitePath, values: siteValues },
    { name: 'env', path: '<stdin>', values: envValues },
  ])

  if (mode === 'origin') {
    for (const declared of SETTINGS) {
      const entry = merged.get(declared.key)
      out.push(`${declared.key} ${entry ? entry.layer : 'default'}`)
    }
  } else {
    for (const declared of SETTINGS) {
      const entry = merged.get(declared.key)
      const text = entry ? entry.text : declared.default
      const result = coerce(declared, text)
      if (!result.ok) fail(`${entry.path}:${entry.line}:${entry.column}: ${result.message}`)
      out.push(`${declared.key}=${result.value}`)
    }
  }
}

process.stdout.write(out.map(line => `${line}\n`).join(''))
"}

